"""Generate small synthetic Logisim 2.7.1 fixtures for parse/sim/lint/backend tests.

Run:  .venv/bin/python tests/fixtures/gen/generate.py
Every generated file is validated by loading it in the real Logisim (`LogisimBridge dump`) when Java and the
jar are available (pass --no-validate to skip).

Functional fixtures connect ports with short wire stubs ending at labelled tunnels (one label per net), which
keeps the geometry trivially collision-free; the lint fixtures are drawn with explicit wires.
"""

from __future__ import annotations

import sys
from dataclasses import dataclass, field
from pathlib import Path
from xml.sax.saxutils import quoteattr

from logilens.core.geometry import Point
from logilens.parse.attrs import resolve_attrs
from logilens.parse.component_specs import compute_ports, find_spec

OUT = Path(__file__).resolve().parent
LIBS = ["#Wiring", "#Gates", "#Plexers", "#Arithmetic", "#Memory", "#I/O", "#Base"]
STUB = 20
_STEP = {"east": (1, 0), "west": (-1, 0), "north": (0, -1), "south": (0, 1)}


@dataclass
class Comp:
    lib: str | None
    name: str
    loc: Point
    attrs: dict[str, str]
    ports: dict[str, Point] = field(default_factory=dict)
    widths: dict[str, int | None] = field(default_factory=dict)


@dataclass
class Circ:
    name: str
    comps: list[Comp] = field(default_factory=list)
    wires: list[tuple[Point, Point]] = field(default_factory=list)

    def add(self, lib: str | None, name: str, x: int, y: int, **attrs: object) -> Comp:
        sattrs = {k: str(v).lower() if isinstance(v, bool) else str(v) for k, v in attrs.items()}
        comp = Comp(lib, name, Point(x, y), sattrs)
        spec = find_spec(lib, name)
        if spec is not None:
            resolved = resolve_attrs(spec.data, sattrs, "2.7.1")
            ports = compute_ports(spec, resolved, comp.loc)
            comp.ports = {p.name: p.loc for p in ports}
            comp.widths = {p.name: p.width for p in ports}
        self.comps.append(comp)
        return comp

    def wire(self, a: tuple[int, int] | Point, b: tuple[int, int] | Point) -> None:
        self.wires.append((Point(*a), Point(*b)))

    def tunnel(self, comp: Comp, port: str, label: str, side: str = "") -> None:
        """Stub wire from a port outwards, ending at a tunnel labelled ``label``."""
        p = comp.ports[port]
        side = side or ("west" if p.x < comp.loc.x else "east")
        dx, dy = _STEP[side]
        end = Point(p.x + dx * STUB, p.y + dy * STUB)
        self.wire(p, end)
        facing = {"east": "west", "west": "east", "north": "south", "south": "north"}[side]
        width = comp.widths.get(port) or 1
        extra = {"width": width} if width > 1 else {}
        self.add("#Wiring", "Tunnel", end.x, end.y, facing=facing, label=label, **extra)

    def xml(self) -> str:
        lib_idx = {d: str(i) for i, d in enumerate(LIBS)}
        lines = [f'  <circuit name={quoteattr(self.name)}>', f'    <a name="circuit" val={quoteattr(self.name)}/>']
        for a, b in self.wires:
            lines.append(f'    <wire from="({a.x},{a.y})" to="({b.x},{b.y})"/>')
        for c in self.comps:
            lib = f' lib="{lib_idx[c.lib]}"' if c.lib else ""
            attrs = "".join(f"\n      <a name={quoteattr(k)} val={quoteattr(v)}/>" for k, v in c.attrs.items())
            close = f">{attrs}\n    </comp>" if attrs else "/>"
            lines.append(f'    <comp{lib} loc="({c.loc.x},{c.loc.y})" name={quoteattr(c.name)}{close}')
        lines.append("  </circuit>")
        return "\n".join(lines)


def project_xml(circuits: list[Circ], main: str = "main") -> str:
    libs = "\n".join(f'  <lib desc="{d}" name="{i}"/>' for i, d in enumerate(LIBS))
    body = "\n".join(c.xml() for c in circuits)
    return (f'<?xml version="1.0" encoding="UTF-8" standalone="no"?>\n<project source="2.7.1" version="1.0">\n'
            f"  Generated by the fixture scripts in tests/fixtures/gen/.\n{libs}\n"
            f'  <main name="{main}"/>\n  <options>\n    <a name="gateUndefined" val="ignore"/>\n'
            f'    <a name="simlimit" val="1000"/>\n    <a name="simrand" val="0"/>\n  </options>\n'
            f"{body}\n</project>\n")


def in_pin(c: Circ, x: int, y: int, label: str, **kw: object) -> Comp:
    return c.add("#Wiring", "Pin", x, y, tristate=False, label=label, **kw)


def out_pin(c: Circ, x: int, y: int, label: str, **kw: object) -> Comp:
    return c.add("#Wiring", "Pin", x, y, facing="west", output=True, labelloc="east", label=label, **kw)


# ------------------------------------------------------------------ lint fixtures (explicit wires)
def dangling() -> list[Circ]:
    c = Circ("main")
    in_pin(c, 100, 100, "a")
    c.wire((100, 100), (150, 100))
    c.wire((150, 100), (200, 100))
    c.add("#Gates", "NOT Gate", 230, 100)
    c.wire((230, 100), (300, 100))
    out_pin(c, 300, 100, "y")
    c.wire((150, 100), (150, 200))  # branch that ends in the air -> L002 at (150,200)
    c.wire((400, 300), (450, 300))  # isolated wire -> two dangling ends
    return [c]


def two_drivers() -> list[Circ]:
    c = Circ("main")
    in_pin(c, 100, 100, "a")
    c.wire((100, 100), (140, 100))
    c.wire((140, 100), (170, 100))
    c.wire((140, 100), (140, 200))
    c.wire((140, 200), (170, 200))
    c.add("#Gates", "NOT Gate", 200, 100)
    c.add("#Gates", "NOT Gate", 200, 200)
    c.wire((200, 100), (250, 100))
    c.wire((200, 200), (250, 200))
    c.wire((250, 100), (250, 200))  # both inverter outputs tied together -> L004
    c.wire((250, 100), (300, 100))
    out_pin(c, 300, 100, "y")
    return [c]


def overlap() -> list[Circ]:
    c = Circ("main")
    in_pin(c, 100, 100, "a")
    c.wire((100, 100), (200, 100))
    c.wire((120, 100), (180, 100))  # lies on top of the first wire -> L006 (+ L005 info for its ends)
    c.add("#Gates", "NOT Gate", 230, 100)
    c.wire((200, 100), (200, 100))  # zero-length wire: dropped like Logisim does
    c.wire((230, 100), (300, 100))
    out_pin(c, 300, 100, "y")
    return [c]


def through_body() -> list[Circ]:
    c = Circ("main")
    in_pin(c, 100, 290, "b")
    c.wire((100, 290), (400, 290))  # passes through the NAND body (x 240..300, y 275..325) -> L007
    out_pin(c, 400, 290, "z")
    in_pin(c, 100, 400, "c")
    c.wire((100, 400), (220, 400))
    c.wire((220, 280), (220, 400))
    c.wire((220, 280), (240, 280))
    c.wire((220, 320), (240, 320))
    c.add("#Gates", "NAND Gate", 300, 300, inputs=2)
    c.wire((300, 300), (350, 300))
    c.wire((350, 300), (350, 350))
    out_pin(c, 350, 350, "w")
    return [c]


def width_mismatch() -> list[Circ]:
    c = Circ("main")
    in_pin(c, 100, 100, "a", width=2)
    c.wire((100, 100), (200, 100))
    out_pin(c, 200, 100, "y")  # 1-bit output on a 2-bit net -> L013
    return [c]


# ------------------------------------------------------------------ functional fixtures (stubs + tunnels)
def comb_loop() -> list[Circ]:
    c = Circ("main")
    s = in_pin(c, 100, 100, "S")
    r = in_pin(c, 100, 200, "R")
    q = out_pin(c, 600, 100, "Q")
    n1 = c.add("#Gates", "NOR Gate", 400, 100, inputs=2)
    n2 = c.add("#Gates", "NOR Gate", 400, 300, inputs=2)
    c.tunnel(s, "pin", "s")
    c.tunnel(r, "pin", "r")
    c.tunnel(n1, "in0", "r")
    c.tunnel(n1, "in1", "qn")
    c.tunnel(n1, "out", "q")
    c.tunnel(n2, "in0", "s")
    c.tunnel(n2, "in1", "q")
    c.tunnel(n2, "out", "qn")
    c.tunnel(q, "pin", "q")
    return [c]


def d_flipflop() -> list[Circ]:
    c = Circ("main")
    d = in_pin(c, 100, 100, "d")
    clk = c.add("#Wiring", "Clock", 100, 200, label="clk")
    ff = c.add("#Memory", "D Flip-Flop", 400, 100)
    q = out_pin(c, 700, 100, "q")
    nq = out_pin(c, 700, 200, "nq")
    c.tunnel(d, "pin", "d")
    c.tunnel(clk, "out", "clk")
    c.tunnel(ff, "d", "d")
    c.tunnel(ff, "clock", "clk")
    c.tunnel(ff, "q", "q")
    c.tunnel(ff, "nq", "nq")
    c.tunnel(q, "pin", "q")
    c.tunnel(nq, "pin", "nq")
    return [c]


def jk_flipflop() -> list[Circ]:
    c = Circ("main")
    j = in_pin(c, 100, 100, "j")
    k = in_pin(c, 100, 200, "k")
    clk = in_pin(c, 100, 300, "clk")
    rst = in_pin(c, 100, 400, "rst")
    ff = c.add("#Memory", "J-K Flip-Flop", 400, 100)
    q = out_pin(c, 700, 100, "q")
    nq = out_pin(c, 700, 200, "nq")
    for pin, lab in ((j, "j"), (k, "k"), (clk, "clk"), (rst, "rst")):
        c.tunnel(pin, "pin", lab)
    c.tunnel(ff, "j", "j")
    c.tunnel(ff, "k", "k")
    c.tunnel(ff, "clock", "clk")
    c.tunnel(ff, "reset", "rst", side="south")
    c.tunnel(ff, "q", "q")
    c.tunnel(ff, "nq", "nq")
    c.tunnel(q, "pin", "q")
    c.tunnel(nq, "pin", "nq")
    return [c]


def moore_fsm() -> list[Circ]:
    """Moore FSM, states z1z2: S0=10, S1=00, S2=01, S3=11; x=0 stay, x=1 next (S0->S1->S2->S3->S0);
    y = 0 only in S0.  D1 = x'z1 + x z2,  D2 = x'z2 + x z1',  y = z1' + z2.  rst=1 forces S0 (preset FF1,
    reset FF2)."""
    c = Circ("main")
    x = in_pin(c, 100, 100, "x")
    rst = in_pin(c, 100, 200, "rst")
    clk = c.add("#Wiring", "Clock", 100, 300, label="clk")
    for pin, lab in ((x, "x"), (rst, "rst")):
        c.tunnel(pin, "pin", lab)
    c.tunnel(clk, "out", "clk")
    nots = [("x", "nx", 300, 100), ("z1", "nz1", 300, 200)]
    for src, dst, gx, gy in nots:
        g = c.add("#Gates", "NOT Gate", gx, gy)
        c.tunnel(g, "in", src)
        c.tunnel(g, "out", dst)
    ands = [("nx", "z1", "t1", 100), ("x", "z2", "t2", 200), ("nx", "z2", "t3", 300), ("x", "nz1", "t4", 400)]
    for a, b, o, gy in ands:
        g = c.add("#Gates", "AND Gate", 500, gy, inputs=2)
        c.tunnel(g, "in0", a)
        c.tunnel(g, "in1", b)
        c.tunnel(g, "out", o)
    for a, b, o, gy in (("t1", "t2", "d1", 100), ("t3", "t4", "d2", 200), ("nz1", "z2", "yv", 300)):
        g = c.add("#Gates", "OR Gate", 700, gy, inputs=2)
        c.tunnel(g, "in0", a)
        c.tunnel(g, "in1", b)
        c.tunnel(g, "out", o)
    ff1 = c.add("#Memory", "D Flip-Flop", 900, 100)
    ff2 = c.add("#Memory", "D Flip-Flop", 900, 300)
    for ff, d, z, setp in ((ff1, "d1", "z1", "preset"), (ff2, "d2", "z2", "reset")):
        c.tunnel(ff, "d", d)
        c.tunnel(ff, "clock", "clk")
        c.tunnel(ff, "q", z)
        c.tunnel(ff, setp, "rst", side="south")
    for lab, y in (("z1", 100), ("z2", 200), ("y", 300)):
        p = out_pin(c, 1200, y, lab)
        c.tunnel(p, "pin", lab if lab != "y" else "yv")
    return [c]


def misc_parts() -> list[Circ]:
    """Multiplexer, decoder, 2-bit adder, comparator, constant, splitter, XOR/XNOR, negated input."""
    c = Circ("main")
    a = in_pin(c, 100, 100, "a", width=2)
    b = in_pin(c, 100, 200, "b", width=2)
    s = in_pin(c, 100, 300, "s")
    c.tunnel(a, "pin", "A", side="east")
    c.tunnel(b, "pin", "B", side="east")
    c.tunnel(s, "pin", "s", side="east")
    sp = c.add("#Wiring", "Splitter", 300, 600, fanout=2, incoming=2)
    c.tunnel(sp, "combined", "A", side="west")
    c.tunnel(sp, "end0", "a0", side="east")
    c.tunnel(sp, "end1", "a1", side="east")
    add = c.add("#Arithmetic", "Adder", 400, 100, width=2)
    c.tunnel(add, "a", "A")
    c.tunnel(add, "b", "B")
    c.tunnel(add, "out", "SUM")
    c.tunnel(add, "carry_out", "COUT", side="south")
    cmp_ = c.add("#Arithmetic", "Comparator", 400, 300, width=2, mode="unsigned")
    c.tunnel(cmp_, "a", "A")
    c.tunnel(cmp_, "b", "B")
    c.tunnel(cmp_, "lt", "LT")
    mux = c.add("#Plexers", "Multiplexer", 600, 500, width=2, enable=False)
    c.tunnel(mux, "in0", "A")
    c.tunnel(mux, "in1", "B")
    c.tunnel(mux, "select", "s", side="south")
    c.tunnel(mux, "out", "M")
    dec = c.add("#Plexers", "Decoder", 600, 700, select=2, enable=False)
    c.tunnel(dec, "select", "B", side="west")
    c.tunnel(dec, "out2", "D2")
    k = c.add("#Wiring", "Constant", 700, 900)
    xo = c.add("#Gates", "XOR Gate", 900, 900, inputs=2)
    c.tunnel(k, "out", "one")
    c.tunnel(xo, "in0", "one")
    c.tunnel(xo, "in1", "a0")
    c.tunnel(xo, "out", "X")
    xn = c.add("#Gates", "XNOR Gate", 900, 1100, inputs=3, negate1=True)
    c.tunnel(xn, "in0", "a1")
    c.tunnel(xn, "in1", "s")
    c.tunnel(xn, "in2", "a0")
    c.tunnel(xn, "out", "XN")
    for i, (lab, net, w) in enumerate((("sum", "SUM", 2), ("cout", "COUT", 1), ("lt", "LT", 1), ("m", "M", 2),
                                       ("d2", "D2", 1), ("x", "X", 1), ("xn", "XN", 1))):
        p = out_pin(c, 1200, 100 + 100 * i, lab, width=w)
        c.tunnel(p, "pin", net)
    return [c]


def subcircuit() -> list[Circ]:
    """main uses a half adder subcircuit twice (one instance facing west)."""
    h = Circ("half")
    a = in_pin(h, 100, 100, "a")
    b = in_pin(h, 100, 200, "b")
    s = out_pin(h, 500, 100, "s")
    co = out_pin(h, 500, 200, "c")
    xo = h.add("#Gates", "XOR Gate", 300, 100, inputs=2)
    an = h.add("#Gates", "AND Gate", 300, 300, inputs=2)
    for pin, lab in ((a, "a"), (b, "b"), (s, "s"), (co, "c")):
        h.tunnel(pin, "pin", lab)
    for g, o in ((xo, "s"), (an, "c")):
        h.tunnel(g, "in0", "a")
        h.tunnel(g, "in1", "b")
        h.tunnel(g, "out", o)
    m = Circ("main")
    pins = [in_pin(m, 100, 100 + 100 * i, n) for i, n in enumerate("xyz")]
    for p, n in zip(pins, "xyz"):
        m.tunnel(p, "pin", n)
    u1 = m.add(None, "half", 400, 200)
    u2 = m.add(None, "half", 700, 400, facing="west")
    m.add("#Wiring", "Probe", 1000, 600)
    outs = [out_pin(m, 1200, 100 + 100 * i, n) for i, n in enumerate(("s", "c1", "c2"))]
    for p, n in zip(outs, ("S", "C1", "C2")):
        m.tunnel(p, "pin", n)
    return [h, m, *_subcircuit_wiring(m, u1, u2)]


def _subcircuit_wiring(m: Circ, u1: Comp, u2: Comp) -> list[Circ]:
    # default appearance of "half" (2 inputs facing east, 2 outputs facing west): inputs at (-30,0),(-30,10),
    # outputs at (0,0),(0,10) relative to loc for an east-facing instance; a west-facing one is rotated 180 deg.
    u1_ports = {"a": (u1.loc.x - 30, u1.loc.y), "b": (u1.loc.x - 30, u1.loc.y + 10),
                "s": (u1.loc.x, u1.loc.y), "c": (u1.loc.x, u1.loc.y + 10)}
    u2_ports = {"a": (u2.loc.x + 30, u2.loc.y), "b": (u2.loc.x + 30, u2.loc.y - 10),
                "s": (u2.loc.x, u2.loc.y), "c": (u2.loc.x, u2.loc.y - 10)}
    for ports, nets, side_in, side_out in ((u1_ports, {"a": "x", "b": "y", "s": "t", "c": "C1"}, -1, 1),
                                           (u2_ports, {"a": "t", "b": "z", "s": "S", "c": "C2"}, 1, -1)):
        for name, (px, py) in ports.items():
            step = side_in if name in "ab" else side_out
            end = (px + step * STUB, py)
            m.wire((px, py), end)
            m.add("#Wiring", "Tunnel", end[0], end[1], facing="east" if step < 0 else "west", label=nets[name])
    return []


FIXTURES = {
    "dangling_wire": dangling, "two_drivers": two_drivers, "overlapping_wires": overlap,
    "wire_through_body": through_body, "width_mismatch": width_mismatch, "comb_loop": comb_loop,
    "d_flipflop": d_flipflop, "jk_flipflop": jk_flipflop, "moore_fsm": moore_fsm, "misc_parts": misc_parts,
    "subcircuit": subcircuit,
}


def main(argv: list[str]) -> int:
    validate = "--no-validate" not in argv
    bridge = None
    if validate:
        from logilens.backends.java.backend import JavaBridge

        bridge = JavaBridge()
    for name, fn in FIXTURES.items():
        circuits = fn()
        main_name = "main" if any(c.name == "main" for c in circuits) else circuits[0].name
        path = OUT / f"{name}.circ"
        path.write_text(project_xml(circuits, main_name), encoding="utf-8")
        if bridge is not None:
            dump = bridge.dump(str(path))  # raises BackendError if Logisim cannot load it
            n = sum(len(c["components"]) for c in dump["circuits"])
            print(f"{path.name}: Logisim loaded {len(dump['circuits'])} circuit(s), {n} components")
        else:
            print(f"{path.name}: written (not validated)")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
